const express = require("express");
const router = express.Router();

module.exports = function (db) {

  router.get("/", async (req, res) =&gt; {
    try {
      const rows = await db.all("SELECT * FROM mood_records");
      res.json(rows);
    } catch (error) {
      res.status(500).json({ error: error.message });
    }
